def test_fuzz_014(run):
    r = run(args=['-t', 'commonmark', '--sourcepos', '--smart'], stdin=b'- *a*b*</b> [\n  ===\n  [ref]: http://x\n- > *... <http://x.y>\\\n  > [link](/u)\n  > [ref][]<b>two words\n  > # *em*  \n  > **strong**  \n  > <!-- c --> #\n  > - - -\n- ```py\n  "q"\\\n  &bogus;\n  "q"  \n  &amp;!\n  ````\n\n<pre>\nword _\n*a*b*\n</div>\n\n    [ _ **strong**\n\na_b_c [link](/u)\n[link](/u)\n\ntwo words<b> word\n---\n\ntwo words ]<!-- c --> \xc3\xa9 <b>  \n*em* <http://x.y>  \n\'s\n')
    assert r.stdout == b'  - # *a*b\\*</b> \\[\n  - > \\*\xe2\x80\xa6 <http://x.y>  \n    > [link](/u)\n    > [ref](http://x)<b>two words\n    > # *em*\n    > **strong**\n    > <!-- c --> #\n    > -----\n  - ``` py\n    "q"\\\n    &bogus;\n    "q"  \n    &amp;!\n    ```\n\n<pre>\nword _\n*a*b*\n</div>\n\n    [ _ **strong**\n\na_b_c [link](/u)\n[link](/u)\n\ntwo words<b> word\n---\n\ntwo words ]<!-- c --> \xc3\xa9 <b>  \n*em* <http://x.y>  \n\'s\n'
    assert r.stderr == b''
    assert r.returncode == 0


