    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <paragraph>\n    <text xml:space="preserve">[</text>\n    <linebreak />\n    <text xml:space="preserve">&amp; </text>\n    <strong>\n      <text xml:space="preserve">strong</text>\n    </strong>\n    <text xml:space="preserve"></text>\n    <linebreak />\n    <text xml:space="preserve">*</text>\n    <image destination="/i.png">\n      <text xml:space="preserve">img</text>\n    </image>\n  </paragraph>\n  <list type="bullet" tight="true">\n    <item>\n      <paragraph>\n        <text xml:space="preserve">--</text>\n        <softbreak />\n        <text xml:space="preserve">~</text>\n        <softbreak />\n        <text xml:space="preserve">...</text>\n        <linebreak />\n        <text xml:space="preserve">[ </text>\n        <emph>\n          <text xml:space="preserve">a </text>\n          <strong>\n            <text xml:space="preserve">b</text>\n          </strong>\n          <text xml:space="preserve"> c</text>\n        </emph>\n        <text xml:space="preserve"></text>\n        <linebreak />\n        <text xml:space="preserve">**</text>\n        <linebreak />\n        <text xml:space="preserve">\'s</text>\n        <softbreak />\n        <text xml:space="preserve">#</text>\n        <linebreak />\n        <html_inline xml:space="preserve">&lt;b&gt;</html_inline>\n        <text xml:space="preserve"> --</text>\n        <softbreak />\n        <text xml:space="preserve">a_b_c</text>\n        <linebreak />\n        <link destination="/u">\n          <text xml:space="preserve">link</text>\n        </link>\n        <text xml:space="preserve">[</text>\n        <linebreak />\n        <text xml:space="preserve">&amp;bogus;</text>\n        <softbreak />\n        <text xml:space="preserve">&amp;</text>\n        <linebreak />\n        <strong>\n          <text xml:space="preserve">strong</text>\n        </strong>\n        <text xml:space="preserve"> &amp;</text>\n        <softbreak />\n        <strong>\n          <text xml:space="preserve">strong</text>\n        </strong>\n        <emph>\n          <text xml:space="preserve">a</text>\n        </emph>\n        <text xml:space="preserve">b* \xf0\x9f\x98\x80</text>\n      </paragraph>\n    </item>\n  </list>\n  <list type="bullet" tight="true">\n    <item />\n  </list>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


