    assert r.stdout == b'.SS\n\\f[I]a\\f[]b*\\-\\-\n&bogus;\n.IP "10." 4\n.SS\n\\f[B]strong\\f[]\n.RS\n.PP\n** \\f[B]strong\\f[]\n##\n.RE\n.IP "11." 4\n|.PD 0\n.P\n.PD\n\xf0\x9f\x98\x80 .PD 0\n.P\n.PD\n\\f[B]strong\\f[] ~ #\n.IP \\[bu] 2\n\\f[B]strong\\f[].PD 0\n.P\n.PD\n~\n.RS\n.RS\n.IP "1." 4\n.SS\n(\\f[I]em\\f[] *\n.PP\nlink (/u)  \xc3\xa9\n[IMAGE: img]\nref (http://x).PD 0\n.P\n.PD\n\\f[I]em\\f[]\nref (http://x):\nhttp://x (t)\n.RE\n.RE\n.IP \\[bu] 2\na@b.c (mailto:a@b.c).PD 0\n.P\n.PD\n\xf0\x9f\x98\x80 # ( \\f[I]em\\f[]\n\\f[I]em\\f[] { ~\n&.PD 0\n.P\n.PD\n\\f[I]a \\f[B]b\\f[]\nc\\f[].PD 0\n.P\n.PD\n&bogus;\n.IP \\[bu] 2\n.SH\n"q"\n.RS\n.PP\nlink (/u)\\f[B]strong\\f[]\n# ####### \xf0\x9f\x98\x80 two\nwordshttp://x.y (http://x.y)\n.RE\n'
    assert r.stderr == b''
