    assert r.stdout == b'<ol data-sourcepos="1:1-44:0">\n<li data-sourcepos="1:1-4:0">\n<pre data-sourcepos="1:8-1:12"><code>*em*\\\n</code></pre>\n</b>\n*em*\n</li>\n<li data-sourcepos="5:1-11:0">\n<pre data-sourcepos="5:4-12:24"><code class="language-py">! *em* \\*  \ntwo words !\n&lt;http://x.y&gt;\n\n---\n\n</code></pre>\n</li>\n<li data-sourcepos="12:1-44:0">\n<blockquote data-sourcepos="12:4-41:9">\n<p data-sourcepos="12:6-13:9"><a href="mailto:a@b.c">a@b.c</a> &amp;bogus; \'s<br />\n*<em>a</em></p>\n<ul data-sourcepos="14:6-35:19">\n<li data-sourcepos="14:6-22:10">\n<pre>\n... </b>&#123; \'s\\\n~\\\n<!-- c -->\n</div>\n**\n[ref][]\n``a`b``\n===\n</li>\n<li data-sourcepos="23:6-28:8">\n<h2 data-sourcepos="23:8-26:9">&quot;q&quot; <em>em</em><br />\na_b_c</h2>\n\'s\n**\n[</li>\n<li data-sourcepos="29:6-31:11">\n<pre data-sourcepos="29:8-31:11"><code class="language-c">_em_\n</code></pre>\n</li>\n<li data-sourcepos="32:6-35:19">\n<h5 data-sourcepos="32:8-32:23"><strong>strong</strong></h5>\n&amp;\n]\n&amp; <code>code</code></li>\n</ul>\n<pre data-sourcepos="36:6-42:7"><code class="language-c">--  \n&amp;#123;)\xc3\xa9  \n\\\n\\* two words\n~~~`\n</code></pre>\n</blockquote>\n<!--\n\xf0\x9f\x98\x80 "q" **a*\n\n</li>\n</ol>\n<h2 data-sourcepos="45:1-51:0">[ref][]\n{\n... [ref]<br />\n<em>em</em><br />\n[ref][]\\</h2>\n<blockquote data-sourcepos="52:1-53:3">\n<pre data-sourcepos="52:7-52:27"><code>__strong__ two words\\\n</code></pre>\n<p data-sourcepos="53:3-53:3">)</p>\n</blockquote>\n<pre data-sourcepos="55:5-55:7"><code>]  \n</code></pre>\n<p data-sourcepos="56:1-56:12">*<em>a</em> [ref][]</p>\n<blockquote data-sourcepos="58:1-64:3">\n<blockquote data-sourcepos="58:3-62:28">\n<p data-sourcepos="58:5-62:28"><a href="/u">link</a><br />\n<em>em</em><br />\n~ <br />\n<b> <em>em</em>\n<code>code</code> <a href="mailto:a@b.c">a@b.c</a> a_b_c <b></p>\n</blockquote>\n<!-- c -->\\\n<p data-sourcepos="64:3-64:3">]</p>\n</blockquote>\n'
