    assert r.stdout == b'.PP\n\\&...\n.RS\n.SS\n~\n.PP\n\\f[I]a\\f[]b* \\f[I]a \\f[B]b\\f[] c\\f[] #\n.RE\n.PP\n  *  *  *  *  *\n'
    assert r.stderr == b''
    assert r.returncode == 0


